// Dos funciones hash para texto: una mala y una buena (FNV-1a de 32 bits)
function hashSuma(texto) {
  let h = 0;
  for (const c of texto) h += c.charCodeAt(0);   // sumar los códigos de los caracteres
  return h;
}
function fnv1a(texto) {
  let h = 0x811c9dc5;                            // valor de arranque fijo (2166136261)
  for (const byte of new TextEncoder().encode(texto)) {
    h ^= byte;                                   // mezclar el byte con XOR
    h = Math.imul(h, 16777619);                  // multiplicar por un primo fijo, conservando 32 bits
  }
  return h >>> 0;                                // leer el resultado como número sin signo
}

