const VACIO = null, LAPIDA = Symbol("lápida");     // lápida: «acá hubo algo y se borró»

class SondeoLineal {
  constructor(capacidad = 8) { this.t = new Array(capacidad).fill(VACIO); }
  _posiciones(clave) {                             // el casillero ideal y los que le siguen, dando la vuelta
    const m = this.t.length, ideal = fnv1a(clave) % m;
    return Array.from({ length: m }, (_, k) => (ideal + k) % m);
  }
  set(clave, valor) {
    for (const p of this._posiciones(clave)) {
      const x = this.t[p];
      if (x === VACIO || x === LAPIDA || x[0] === clave) { this.t[p] = [clave, valor]; return p; }
    }
    throw new Error("tabla llena");
  }
  get(clave) {
    for (const p of this._posiciones(clave)) {
      const x = this.t[p];
      if (x === VACIO) return undefined;           // un casillero vacío corta la búsqueda: la clave no está
      if (x !== LAPIDA && x[0] === clave) return x[1];
    }
    return undefined;
  }
  borrar(clave, conLapida) {
    for (const p of this._posiciones(clave)) {
      const x = this.t[p];
      if (x === VACIO) return false;
      if (x !== LAPIDA && x[0] === clave) { this.t[p] = conLapida ? LAPIDA : VACIO; return true; }
    }
    return false;
  }
  ver() { return this.t.map(x => x === VACIO ? "." : x === LAPIDA ? "#" : x[0].slice(3)).join(" "); }
}

