// ¿Cuánto trabajo extra cuesta agrandar la tabla? Contamos cuántas veces se recoloca una clave.
function costoTotal(n, crecer) {
  let capacidad = 8, usados = 0, recolocadas = 0;
  for (let i = 0; i < n; i++) {
    if (usados + 1 > capacidad * 0.75) {   // pasaría el 75 % de carga: hay que agrandar
      recolocadas += usados;               // y volver a calcular el casillero de cada clave
      capacidad = crecer(capacidad);
    }
    usados++;
  }
  return recolocadas;
}
for (const n of [1000, 10000, 100000]) {
  const duplicando = costoTotal(n, c => c * 2);
  const sumandoDiez = costoTotal(n, c => c + 10);
  console.log("n =", n, "| duplicando:", (duplicando / n).toFixed(2), "recolocaciones por inserción | sumando 10:", (sumandoDiez / n).toFixed(1));
}

