// El hash de las cadenas de Java: h = 31*h + carácter, con desborde a 32 bits (así lo define su documentación)
function hashJava(texto) {
  let h = 0;
  for (let i = 0; i < texto.length; i++) h = (Math.imul(31, h) + texto.charCodeAt(i)) | 0;
  return h;
}
console.log("Aa:", hashJava("Aa"), " BB:", hashJava("BB"));          // las dos dan 2112
console.log("AaAa:", hashJava("AaAa"), " BBBB:", hashJava("BBBB"), " AaBB:", hashJava("AaBB"));

// Cada bloque «Aa» se puede cambiar por «BB» sin tocar el hash: con k bloques salen 2^k claves distintas con el mismo hash
function claveQueColisionan(k) {
  let claves = [""];
  for (let i = 0; i < k; i++) claves = claves.flatMap(c => [c + "Aa", c + "BB"]);
  return claves;
}
const malas = claveQueColisionan(11);                               // 2.048 claves
console.log("claves distintas:", new Set(malas).size, "| hashes distintos:", new Set(malas.map(hashJava)).size);

// Una tabla de juguete con sondeo lineal que cuenta cuántas casillas mira en total (no es el HashMap real de Java)
function casillasMiradas(claves, capacidad) {
  const tabla = new Array(capacidad).fill(null);
  let mirados = 0;
  for (const c of claves) {
    let p = (hashJava(c) >>> 0) % capacidad;
    while (tabla[p] !== null) { p = (p + 1) % capacidad; mirados++; }
    tabla[p] = c;
    mirados++;
  }
  return mirados;
}
