// Una tabla hash con encadenamiento, hecha desde cero
function fnv1a(texto) {
  let h = 0x811c9dc5;
  for (const byte of new TextEncoder().encode(texto)) {
    h ^= byte;
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

class TablaHash {
  constructor(capacidad = 4) {
    this.casilleros = Array.from({ length: capacidad }, () => []);   // cada casillero es una lista de pares [clave, valor]
    this.tamanio = 0;
    this.agrandadas = 0;
  }
  _casillero(clave) {
    return this.casilleros[fnv1a(clave) % this.casilleros.length];
  }
  set(clave, valor) {
    const lista = this._casillero(clave);
    for (const par of lista) {
      if (par[0] === clave) { par[1] = valor; return; }               // la clave ya estaba: se reemplaza el valor
    }
    lista.push([clave, valor]);
    this.tamanio++;
    if (this.tamanio / this.casilleros.length > 0.75) this._agrandar();
  }
  get(clave) {
    for (const par of this._casillero(clave)) {
      if (par[0] === clave) return par[1];
    }
    return undefined;
  }
  delete(clave) {
    const lista = this._casillero(clave);
    const i = lista.findIndex(par => par[0] === clave);
    if (i === -1) return false;
    lista.splice(i, 1);
    this.tamanio--;
    return true;
  }
  _agrandar() {
    const viejos = this.casilleros;
    this.casilleros = Array.from({ length: viejos.length * 2 }, () => []);
    for (const lista of viejos)
      for (const [clave, valor] of lista)
        this._casillero(clave).push([clave, valor]);                  // el casillero depende del tamaño: se recalcula
    this.agrandadas++;
  }
  carga() { return this.tamanio / this.casilleros.length; }
}

